"""domains — 切换意图域（游戏 / 运维 / 日常）

用户口径：默认领域 = 日常（能打开网站/网页这些意图）；说一句就能切：
  · domain_daily  「切换到日常 / 日常模式 / 回到日常」
  · domain_game   「切换到游戏 / 游戏模式 / 回到游戏」
  · domain_ops    「切换到运维 / 运维模式 / 回到运维」
切完立即重建匹配表（热加载），并把新口径打一行 INFO；选择按 profile 落盘
（opencode_fastpath/domain_state.json），重启仍然是这个域。
"""
from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def _switch(cfg, dom, dry=False):
    from opencode_fastpath import intents as _intents
    if dry:
        return True, f"[dry] 切换意图域 → {dom}", {"domain": dom}
    old = _intents.domain_of(cfg)
    nm = _intents.set_domain(cfg, dom)
    if nm is None:
        return False, f"切换失败：不认识的领域 {dom!r}（可选：日常 / 游戏 / 运维）", None
    s = _intents.summary(cfg)
    return True, (f"意图域：{old} → {nm}（已生效，无需重启）｜ {s}"
                  f"；说「切换到游戏/运维/日常」可随时再切"), {"domain": nm, "from": old}


def act_domain_daily(arg, cfg, dry=False):
    return _switch(cfg, "日常", dry)


def act_domain_game(arg, cfg, dry=False):
    return _switch(cfg, "游戏", dry)


def act_domain_ops(arg, cfg, dry=False):
    return _switch(cfg, "运维", dry)


if __name__ == "__main__":
    import sys
    sys.path.insert(0, str(ROOT))
    from actions import Config
    from opencode_fastpath import intents
    cfg = Config(sys.argv[1] if len(sys.argv) > 1 else None)
    print("当前域:", intents.domain_of(cfg))
    for dom in ("游戏", "运维", "日常"):
        print(" ", _switch(cfg, dom)[1][:120])
    print("最终:", intents.summary(cfg))
